from itertools import product

people = ["G", "H", "K", "L", "P", "S"]
sols = []
for assign in product([1, 2, 3], repeat=6):
    d = dict(zip(people, assign))
    if any(list(assign).count(day) != 2 for day in (1, 2, 3)):
        continue
    if d["L"] != d["P"]:
        continue
    if d["G"] == d["H"]:
        continue
    if d["K"] == 1 and d["G"] != 2:
        continue
    if d["S"] == 3 and d["H"] != 2:
        continue
    sols.append(d)

print("valid arrangements:", len(sols))

options = {
    "A": lambda d: d["G"] == d["S"],
    "B": lambda d: d["S"] != d["H"],
    "C": lambda d: d["K"] != d["S"],
    "D": lambda d: d["K"] != d["G"],
}

must = []
for k, f in options.items():
    holds = sum(1 for d in sols if f(d))
    counter = next((d for d in sols if not f(d)), None)
    print(k, "holds in", holds, "of", len(sols), "| counterexample:", counter)
    if sols and holds == len(sols):
        must.append(k)

print("must-be-true options:", must)
submitted = "B"
if not sols:
    print("CHECK UNKNOWN")
elif must == [submitted]:
    print("CHECK PASS")
else:
    print("CHECK FAIL")
